def _is_bool(series: pd.Series) -> bool:
    values = series.dropna()
    return values.map(lambda v: isinstance(v, (bool, np.bool_)) or str(v) in ("True", "False")).all() if len(values) else True


def validate_frame(name: str, frame: pd.DataFrame) -> list[str]:
    """Errors for one file. Missing or unknown column, a null in a required column, a bad type or enum, a repeated key."""
    spec = SCHEMAS[name]
    errors = []
    expected = [c[0] for c in spec["columns"]]
    missing, unknown = sorted(set(expected) - set(frame.columns)), sorted(set(frame.columns) - set(expected))
    if missing:
        errors.append(f"missing columns {missing}")
    if unknown:
        errors.append(f"unknown columns {unknown}")
    for column in spec["columns"]:
        name_, kind, _, nullable = column[:4]
        if name_ not in frame.columns:
            continue
        s = frame[name_]
        if not nullable and s.isna().any():
            errors.append(f"{name_}: {int(s.isna().sum())} nulls in a required column")
        values = s.dropna()
        if kind == "enum" and (~values.isin(column[5])).any():
            errors.append(f"{name_}: values outside the enum {sorted(set(values) - set(column[5]))[:5]}")
        elif kind in ("float", "int", "prob"):
            numeric = pd.to_numeric(values, errors="coerce")
            if numeric.isna().any():
                errors.append(f"{name_}: not numeric")
            elif kind == "int" and ((numeric % 1) != 0).any():
                errors.append(f"{name_}: not whole numbers")
            elif kind == "prob" and ((numeric < 0) | (numeric > 1)).any():
                errors.append(f"{name_}: outside 0 to 1")
        elif kind == "bool" and not _is_bool(values):
            errors.append(f"{name_}: not boolean")
    pk = [c for c in spec["pk"] if c in frame.columns]
    if len(pk) == len(spec["pk"]) and frame.duplicated(pk).any():
        errors.append(f"primary key {spec['pk']} repeats on {int(frame.duplicated(pk).sum())} rows")
    return errors


def validate_all(files: dict) -> list[dict]:
    rows = []
    for name, frame in files.items():
        errors = validate_frame(name, frame)
        rows.append({"check_id": f"schema_{name}", "expected": "[]", "actual": str(errors), "status": "PASS" if not errors else "FAIL"})
    return rows


def render_markdown() -> str:
    lines = [
        "# INSpire Engine Output Contract v0.2", "",
        "**Status:** generated from `src/simulation/contract.py`. Do not edit by hand. This is contract v0.1 plus Addenda A and B, extended. It does not replace them with a competing contract: every v0.1 column keeps its name and meaning, and v0.2 only adds columns, files and enum values. See the change log in `TEAM_INTEGRATION_PROTOCOL.md`.", "",
        "**Paths.** Real output: `data/processed/engine/` (git-ignored, confidential, blocked from deployment by D-07). Labelled sample output: `data/samples/engine/` (invented material numbers, safe to deploy).", "",
        "**Rules that apply to every file.** CSV, UTF-8. Blank means no value, never zero. Read `material_no` as text. `output_class` says what each row is, and `sample` rows are never results. Do not recalculate any value. Do not sum quantities across units or amounts across currencies. There is no default demand scenario or PR PO view.", "",
        "**Manifest.** `eng_run_manifest.json` has `run_id`, `spec_version`, `engine_version`, `methodology_version`, `data_label`, `simulated_label`, `seed`, `replications`, `input_checksums`, `created_at`, `execution_status`, `assumptions`, `populations` and, for each file, rows, sha256, grain, output classes, seed, population and assumptions. A loader must reject a run with no manifest or no `data_label`.", "",
        "**Scenario grammar.** `SC-<D>-<V>-<P>-<S>-<K>`. D: A, B. V: OR, ED. P: R0, R1, R2, N1, X1, X2, X3. S: BO, LS. K: `eng_config_registry.csv`. N1 is new in v0.2. `SC-ALL-NA-NA-NA-K0` marks a scenario-independent row. Forecast rows use `NA` inside `scenario_id` for the parts they do not depend on. Read every CSV with default null-string parsing off, or `SC-` values and units can be damaged.", ""]
    for name, spec in SCHEMAS.items():
        lines += [f"## `{name}`", "", f"- **Grain:** {spec['grain']}", f"- **Primary key:** {', '.join(f'`{c}`' for c in spec['pk'])}", f"- **Population:** {spec['population']}", f"- **Scenario identification:** {spec['scenario']}", f"- **Evidence:** {spec['evidence']}", "", "| Column | Type | Unit | Null allowed | Meaning |", "| --- | --- | --- | --- | --- |"]
        for c in spec["columns"]:
            lines.append(f"| `{c[0]}` | {c[1]} | {c[2] or ''} | {'yes' if c[3] else 'no'} | {c[4]} |")
        lines.append("")
    return "\n".join(lines)
